INSERT INTO linearalgebra (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the magnitude of the vector v = (3, 4)?', '5', '7', '12', '25', '5', 'The magnitude is sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5.', 700, 'LinearAlgebra'),
('What is the dot product of u = (2, -1, 3) and v = (1, 4, 2)?', '4', '6', '-2', '10', '4', 'Dot product: 2*1 + (-1)*4 + 3*2 = 2 - 4 + 6 = 4.', 720, 'LinearAlgebra'),
('Two vectors are orthogonal if their dot product is:', '0', '1', '-1', 'undefined', '0', 'Orthogonal (perpendicular) vectors have a dot product of zero.', 710, 'LinearAlgebra'),
('What is the cross product of i = (1,0,0) and j = (0,1,0)?', 'k = (0,0,1)', '-k = (0,0,-1)', '(1,1,0)', '(0,0,0)', 'k = (0,0,1)', 'i x j = k by the right-hand rule for the standard basis cross products.', 760, 'LinearAlgebra'),
('What is the determinant of the 2x2 matrix [[3,1],[2,4]]?', '10', '14', '-10', '7', '10', 'det[[a,b],[c,d]] = ad - bc = 3*4 - 1*2 = 12 - 2 = 10.', 730, 'LinearAlgebra'),
('Which of the following sets of vectors is linearly independent?', '{(1,0),(0,1)}', '{(2,4),(1,2)}', '{(0,0),(1,2)}', '{(3,6),(1,2)}', '{(1,0),(0,1)}', 'The standard basis vectors (1,0) and (0,1) cannot be written as scalar multiples of each other, so they are linearly independent.', 780, 'LinearAlgebra'),
('The span of vectors v1 and v2 is:', 'All linear combinations c1*v1 + c2*v2', 'The dot product of v1 and v2', 'The cross product of v1 and v2', 'The set {v1, v2} only', 'All linear combinations c1*v1 + c2*v2', 'The span is the set of all vectors that can be formed as linear combinations of the given set.', 750, 'LinearAlgebra'),
('What is the transpose of the matrix [[1,2,3],[4,5,6]]?', '[[1,4],[2,5],[3,6]]', '[[4,5,6],[1,2,3]]', '[[1,2],[3,4],[5,6]]', '[[6,5,4],[3,2,1]]', '[[1,4],[2,5],[3,6]]', 'The transpose swaps rows and columns: the (i,j) entry becomes the (j,i) entry.', 740, 'LinearAlgebra'),
('A square matrix A is invertible if and only if:', 'det(A) != 0', 'det(A) = 0', 'A is symmetric', 'A has all positive entries', 'det(A) != 0', 'A matrix is invertible (non-singular) precisely when its determinant is non-zero, equivalently when its rows (or columns) are linearly independent.', 800, 'LinearAlgebra'),
('For a 3x3 matrix, what is the size of the identity matrix I that satisfies A*I = A?', '3x3', '1x1', '3x1', '1x3', '3x3', 'The identity matrix must have the same dimensions as the matrix it multiplies; for a 3x3 matrix, I is 3x3.', 710, 'LinearAlgebra'),
('What is the trace of the matrix [[4,1],[2,3]]?', '7', '10', '5', '-2', '7', 'The trace is the sum of the diagonal entries: 4 + 3 = 7.', 720, 'LinearAlgebra'),
('Gaussian elimination converts a matrix to:', 'Row echelon form', 'Column echelon form', 'Diagonal form', 'Symmetric form', 'Row echelon form', 'Gaussian elimination uses elementary row operations to produce a row echelon (upper triangular) form, from which back substitution solves the system.', 800, 'LinearAlgebra'),
('How many solutions does the system Ax = b have when A is a 3x3 matrix with det(A) = 0 and b != 0?', 'Either zero or infinitely many', 'Exactly one', 'Exactly two', 'Always zero', 'Either zero or infinitely many', 'When det(A) = 0 the matrix is singular; the system has either no solutions or infinitely many, depending on b.', 950, 'LinearAlgebra'),
('The rank of a matrix equals:', 'The number of pivots in its row echelon form', 'The number of rows', 'The number of columns', 'The determinant', 'The number of pivots in its row echelon form', 'Rank is the dimension of the column space, which equals the number of non-zero pivot positions after row reduction.', 870, 'LinearAlgebra'),
('If A is an m x n matrix, what is the rank-nullity theorem?', 'rank(A) + nullity(A) = n', 'rank(A) + nullity(A) = m', 'rank(A) * nullity(A) = m*n', 'rank(A) - nullity(A) = 0', 'rank(A) + nullity(A) = n', 'The rank-nullity theorem states that rank plus nullity equals the number of columns n of the matrix.', 1050, 'LinearAlgebra'),
('What is the nullspace of a matrix A?', 'The set of all x such that Ax = 0', 'The set of all Ax for any x', 'The set of pivot columns of A', 'The set of rows of A', 'The set of all x such that Ax = 0', 'The nullspace (kernel) consists of all vectors x that map to the zero vector under the linear transformation A.', 900, 'LinearAlgebra'),
('Which property must a subset W of a vector space V satisfy to be a subspace?', 'Closed under addition and scalar multiplication, and contains 0', 'Contains at least two vectors', 'Is finite and non-empty', 'All vectors in W are orthogonal', 'Closed under addition and scalar multiplication, and contains 0', 'A subspace must contain the zero vector and be closed under addition and scalar multiplication.', 1000, 'LinearAlgebra'),
('A basis of a vector space V is:', 'A linearly independent set that spans V', 'Any spanning set of V', 'Any linearly independent set in V', 'The set of all vectors in V', 'A linearly independent set that spans V', 'A basis is a minimal spanning set; it must be linearly independent and its span must equal the entire space.', 950, 'LinearAlgebra'),
('What is the dimension of the vector space R^4?', '4', '1', '16', 'infinite', '4', 'The dimension of R^n is n; the standard basis {e1, e2, e3, e4} has 4 vectors.', 720, 'LinearAlgebra'),
('If lambda is an eigenvalue of A, then det(A - lambda*I) equals:', '0', '1', 'lambda', 'det(A)', '0', 'Eigenvalues satisfy the characteristic equation det(A - lambda*I) = 0, which yields the characteristic polynomial.', 900, 'LinearAlgebra'),
('The characteristic polynomial of [[2,1],[0,3]] is:', '(lambda-2)(lambda-3)', '(lambda+2)(lambda+3)', 'lambda^2 - 1', 'lambda^2 - 5*lambda + 5', '(lambda-2)(lambda-3)', 'The matrix is upper triangular, so eigenvalues are diagonal entries 2 and 3; characteristic polynomial = (lambda-2)(lambda-3).', 1050, 'LinearAlgebra'),
('A matrix A is diagonalizable if:', 'It has n linearly independent eigenvectors', 'Its determinant is non-zero', 'It is symmetric', 'It has distinct entries', 'It has n linearly independent eigenvectors', 'An n x n matrix is diagonalizable if and only if it has n linearly independent eigenvectors, allowing A = P*D*P^{-1}.', 1150, 'LinearAlgebra'),
('What does it mean for a matrix to be orthogonally diagonalizable?', 'A = Q*D*Q^T where Q is orthogonal and D is diagonal', 'A = P*D*P^{-1} for some invertible P', 'A has only real eigenvalues', 'A is both symmetric and invertible', 'A = Q*D*Q^T where Q is orthogonal and D is diagonal', 'The spectral theorem states that real symmetric matrices are orthogonally diagonalizable: A = Q*D*Q^T with Q^T = Q^{-1}.', 1350, 'LinearAlgebra'),
('A linear transformation T: R^n -> R^m is represented by a matrix A. What is T(0)?', '0', 'A', 'I', 'undefined', '0', 'Every linear transformation maps the zero vector to the zero vector: T(0) = T(0*v) = 0*T(v) = 0.', 750, 'LinearAlgebra'),
('The composition of two linear transformations T: R^n -> R^m and S: R^m -> R^k corresponds to:', 'Matrix product S*T (S composed with T)', 'Matrix sum S + T', 'Matrix product T*S', 'The tensor product S⊗T', 'Matrix product S*T (S composed with T)', 'Composition (S after T) corresponds to multiplying the associated matrices in the same order: [S∘T] = [S][T].', 1100, 'LinearAlgebra'),
('The projection of vector u onto vector v is:', 'proj_v(u) = (u·v / v·v) * v', 'proj_v(u) = (u·v) * v', 'proj_v(u) = u - v', 'proj_v(u) = u x v', 'proj_v(u) = (u·v / v·v) * v', 'The orthogonal projection of u onto v is the scalar (u·v)/(v·v) times the unit direction v.', 1000, 'LinearAlgebra'),
('Gram-Schmidt orthogonalization takes a basis and produces:', 'An orthonormal basis spanning the same subspace', 'An orthogonal matrix with the same determinant', 'A diagonal matrix', 'A set of linearly dependent vectors', 'An orthonormal basis spanning the same subspace', 'Gram-Schmidt iteratively subtracts projections to produce an orthogonal set, which is then normalized to give an orthonormal basis.', 1200, 'LinearAlgebra'),
('A matrix Q is orthogonal if:', 'Q^T * Q = I', 'Q * Q = I', 'Q + Q^T = I', 'det(Q) = 0', 'Q^T * Q = I', 'An orthogonal matrix has Q^T = Q^{-1}, equivalently Q^T*Q = I; its columns form an orthonormal set.', 1000, 'LinearAlgebra'),
('What is the determinant of an orthogonal matrix Q?', '+1 or -1', '0', 'Any real number', 'Always +1', '+1 or -1', 'Since det(Q^T*Q) = det(I) = 1 and det(Q^T) = det(Q), we get det(Q)^2 = 1, so det(Q) = ±1.', 1150, 'LinearAlgebra'),
('For a symmetric matrix A, eigenvectors corresponding to distinct eigenvalues are:', 'Orthogonal', 'Parallel', 'Linearly dependent', 'Equal in magnitude', 'Orthogonal', 'The spectral theorem guarantees that for real symmetric A, eigenvectors for different eigenvalues are automatically orthogonal.', 1200, 'LinearAlgebra'),
('The singular value decomposition (SVD) of an m x n matrix A is:', 'A = U*Sigma*V^T', 'A = P*D*P^{-1}', 'A = L*U', 'A = Q*R', 'A = U*Sigma*V^T', 'SVD decomposes any matrix as A = U*Sigma*V^T, where U and V are orthogonal and Sigma is diagonal with non-negative singular values.', 1500, 'LinearAlgebra'),
('The singular values of A are:', 'Square roots of the eigenvalues of A^T*A', 'Eigenvalues of A', 'Diagonal entries of A', 'Square roots of the diagonal entries of A', 'Square roots of the eigenvalues of A^T*A', 'The singular values sigma_i = sqrt(lambda_i(A^T*A)); they are non-negative and characterize the "stretching" of A.', 1600, 'LinearAlgebra'),
('What is the rank of A = [[1,2,3],[2,4,6],[0,0,0]]?', '1', '2', '3', '0', '1', 'Row 2 = 2*row 1 and row 3 = 0; after row reduction there is exactly one pivot, so rank = 1.', 1000, 'LinearAlgebra'),
('A system of linear equations Ax = b is consistent if and only if:', 'b is in the column space of A', 'b is in the nullspace of A', 'det(A) = 0', 'A is square', 'b is in the column space of A', 'Ax = b is consistent precisely when b can be written as a linear combination of the columns of A, i.e., b ∈ col(A).', 1050, 'LinearAlgebra'),
('The LU decomposition of a matrix A factors it as:', 'A lower triangular matrix L times an upper triangular matrix U', 'An orthogonal matrix Q times a triangular matrix R', 'A diagonal matrix D times an orthogonal matrix', 'A product of elementary matrices only', 'A lower triangular matrix L times an upper triangular matrix U', 'LU decomposition factors A = L*U where L is lower triangular with 1s on the diagonal and U is upper triangular; it facilitates solving Ax = b efficiently.', 1200, 'LinearAlgebra'),
('What is the inverse of a 2x2 matrix [[a,b],[c,d]]?', '(1/(ad-bc)) * [[d,-b],[-c,a]]', '(1/(ad-bc)) * [[a,b],[c,d]]', '[[d,b],[c,a]] / (ad+bc)', '[[a,-b],[-c,d]] / (ad-bc)', '(1/(ad-bc)) * [[d,-b],[-c,a]]', 'The inverse of [[a,b],[c,d]] is (1/det)*[[d,-b],[-c,a]], where det = ad - bc.', 900, 'LinearAlgebra'),
('The column space of a matrix A is:', 'The span of the columns of A', 'The span of the rows of A', 'The set of solutions to Ax = 0', 'The set of diagonal entries of A', 'The span of the columns of A', 'The column space (image) of A is {Ax : x in R^n}, which is exactly the span of the columns of A.', 900, 'LinearAlgebra'),
('For a 4x4 matrix with eigenvalues 1, 2, 2, 3, what is the trace?', '8', '6', '12', '7', '8', 'The trace equals the sum of all eigenvalues: 1 + 2 + 2 + 3 = 8.', 1050, 'LinearAlgebra'),
('For a 4x4 matrix with eigenvalues 1, 2, 2, 3, what is the determinant?', '12', '8', '6', '24', '12', 'The determinant equals the product of all eigenvalues: 1 * 2 * 2 * 3 = 12.', 1100, 'LinearAlgebra'),
('Which matrix operation is NOT always commutative?', 'Matrix multiplication', 'Matrix addition', 'Scalar multiplication', 'Transposition of a sum', 'Matrix multiplication', 'In general A*B != B*A for matrix multiplication; the other operations (addition, scalar multiplication) are commutative.', 780, 'LinearAlgebra'),
('The Cayley-Hamilton theorem states that:', 'Every matrix satisfies its own characteristic polynomial', 'Every matrix has n distinct eigenvalues', 'Eigenvalues equal diagonal entries', 'det(A - lambda*I) = det(A)', 'Every matrix satisfies its own characteristic polynomial', 'Cayley-Hamilton: if p(lambda) = det(A - lambda*I) is the characteristic polynomial, then p(A) = 0 (the zero matrix).', 1500, 'LinearAlgebra'),
('If A is a 5x3 matrix, what is the maximum possible rank of A?', '3', '5', '8', '15', '3', 'Rank is at most min(m, n) = min(5, 3) = 3; it cannot exceed the number of columns or rows.', 870, 'LinearAlgebra'),
('What is the formula for the angle theta between two nonzero vectors u and v?', 'cos(theta) = (u·v) / (|u|*|v|)', 'cos(theta) = |u x v| / (|u|*|v|)', 'theta = u·v', 'sin(theta) = (u·v) / (|u|*|v|)', 'cos(theta) = (u·v) / (|u|*|v|)', 'The angle between vectors is given by the dot product formula: u·v = |u||v|cos(theta), so cos(theta) = (u·v)/(|u||v|).', 820, 'LinearAlgebra'),
('A matrix is positive definite if:', 'All its eigenvalues are strictly positive', 'Its determinant is positive', 'It is symmetric with positive entries', 'It has positive trace', 'All its eigenvalues are strictly positive', 'A real symmetric matrix is positive definite if and only if all its eigenvalues are strictly positive, equivalently if x^T*A*x > 0 for all nonzero x.', 1400, 'LinearAlgebra'),
('What is the geometric multiplicity of an eigenvalue lambda_0?', 'The dimension of the eigenspace ker(A - lambda_0*I)', 'The multiplicity of lambda_0 as a root of the characteristic polynomial', 'The trace of (A - lambda_0*I)', 'The rank of (A - lambda_0*I)', 'The dimension of the eigenspace ker(A - lambda_0*I)', 'Geometric multiplicity is the dimension of the nullspace of (A - lambda_0*I), i.e., the number of linearly independent eigenvectors for that eigenvalue.', 1350, 'LinearAlgebra'),
('The QR decomposition writes A as:', 'An orthogonal matrix Q times an upper triangular matrix R', 'A lower triangular L times upper triangular U', 'A diagonal D times an orthogonal Q', 'A permutation P times an invertible matrix', 'An orthogonal matrix Q times an upper triangular matrix R', 'QR decomposition factors A = Q*R where Q has orthonormal columns (Q^T*Q = I) and R is upper triangular; it arises from Gram-Schmidt.', 1300, 'LinearAlgebra'),
('The pseudoinverse (Moore-Penrose inverse) A^+ of a matrix A satisfies:', 'A*A^+*A = A', 'A^+*A = I always', '(A^+)^T = A', 'A^+*A^+ = A', 'A*A^+*A = A', 'The pseudoinverse satisfies four Moore-Penrose conditions; the key one is A*A^+*A = A, generalizing the inverse to non-square/singular matrices.', 1800, 'LinearAlgebra'),
('If A is an n x n matrix with n linearly independent eigenvectors P = [v1,...,vn], then A = ?', 'P*D*P^{-1} where D is diagonal with eigenvalues', 'P^{-1}*D*P where D has eigenvectors', 'D*P where D is diagonal', 'P*P^T', 'P*D*P^{-1} where D is diagonal with eigenvalues', 'Diagonalization gives A = P*D*P^{-1} where columns of P are eigenvectors and D has corresponding eigenvalues on its diagonal.', 1250, 'LinearAlgebra'),
('What is the best (least-squares) solution x* to the inconsistent system Ax = b?', 'x* = (A^T*A)^{-1}*A^T*b (when A^T*A is invertible)', 'x* = A^{-1}*b', 'x* = A^T*b', 'x* = (A*A^T)^{-1}*b', 'x* = (A^T*A)^{-1}*A^T*b (when A^T*A is invertible)', 'The least-squares solution minimizes ||Ax - b||^2 and satisfies the normal equations A^T*A*x = A^T*b, giving x* = (A^T*A)^{-1}*A^T*b.', 1600, 'LinearAlgebra'),
('The four fundamental subspaces of an m x n matrix A are:', 'col(A), null(A), col(A^T), null(A^T)', 'row(A), col(A), diag(A), null(A)', 'span(A), kernel(A), image(A), coimage(A)', 'col(A), null(A), eigenspace(A), trace(A)', 'col(A), null(A), col(A^T), null(A^T)', 'The four fundamental subspaces are the column space, nullspace, row space (= col(A^T)), and left nullspace (= null(A^T)), which come in orthogonal complement pairs.', 1700, 'LinearAlgebra');
